        )
    }

    #[test]
    fn test_empty_index() {
        let index = SpatialIndex::new();
        assert!(index.is_empty());
        assert_eq!(index.len(), 0);
    }

    #[test]
    fn test_rebuild_and_len() {
        let mut index = SpatialIndex::new();
        let entries = vec![
            make_entry(0, (0.0, 0.0), (10.0, 10.0), 1),
            make_entry(1, (20.0, 20.0), (30.0, 30.0), 1),
        ];
        index.rebuild(entries);

        assert!(!index.is_empty());
        assert_eq!(index.len(), 2);
    }

    #[test]
    fn test_query_region_finds_intersecting() {
        let mut index = SpatialIndex::new();
        index.rebuild(vec![
            make_entry(0, (0.0, 0.0), (10.0, 10.0), 1),
            make_entry(1, (5.0, 5.0), (15.0, 15.0), 1),
            make_entry(2, (100.0, 100.0), (110.0, 110.0), 1),
        ]);

        // Query overlapping region - should find entries 0 and 1
        let found: Vec<_> = index
            .query_region(Point::from_mm(4.0, 4.0), Point::from_mm(6.0, 6.0))
            .collect();
        assert_eq!(found.len(), 2);

        // Query region only overlapping entry 2
        let found: Vec<_> = index
            .query_region(Point::from_mm(105.0, 105.0), Point::from_mm(106.0, 106.0))
            .collect();
        assert_eq!(found.len(), 1);
        assert_eq!(found[0], Entity::from_raw(2));
    }

    #[test]
    fn test_query_region_no_match() {
        let mut index = SpatialIndex::new();
        index.rebuild(vec![make_entry(0, (0.0, 0.0), (10.0, 10.0), 1)]);

        let found: Vec<_> = index
            .query_region(Point::from_mm(50.0, 50.0), Point::from_mm(60.0, 60.0))
            .collect();
        assert!(found.is_empty());
    }

    #[test]
    fn test_query_point() {
        let mut index = SpatialIndex::new();
        index.rebuild(vec![
            make_entry(0, (0.0, 0.0), (10.0, 10.0), 1),
            make_entry(1, (5.0, 5.0), (15.0, 15.0), 1),
        ]);

        // Point inside only entry 0
        let found: Vec<_> = index.query_point(Point::from_mm(2.0, 2.0)).collect();
        assert_eq!(found.len(), 1);
        assert_eq!(found[0], Entity::from_raw(0));

        // Point inside both entries
        let found: Vec<_> = index.query_point(Point::from_mm(7.0, 7.0)).collect();
        assert_eq!(found.len(), 2);
    }

    #[test]
    fn test_layer_filtering() {
        let mut index = SpatialIndex::new();
        index.rebuild(vec![
            make_entry(0, (0.0, 0.0), (10.0, 10.0), 0b01), // Top only
            make_entry(1, (0.0, 0.0), (10.0, 10.0), 0b10), // Bottom only
            make_entry(2, (0.0, 0.0), (10.0, 10.0), 0b11), // Both
        ]);

        // Query top layer only
        let found: Vec<_> = index
            .query_region_on_layers(
                Point::from_mm(0.0, 0.0),
                Point::from_mm(10.0, 10.0),
                0b01,
            )
            .collect();
        assert_eq!(found.len(), 2); // Entries 0 and 2

        // Query bottom layer only
        let found: Vec<_> = index
            .query_region_on_layers(
                Point::from_mm(0.0, 0.0),
                Point::from_mm(10.0, 10.0),
                0b10,
            )
            .collect();
        assert_eq!(found.len(), 2); // Entries 1 and 2
    }

    #[test]
    fn test_entry_layer_methods() {
        let entry = make_entry(0, (0.0, 0.0), (10.0, 10.0), 0b101); // Layers 0 and 2

        assert!(entry.on_layer(0));
        assert!(!entry.on_layer(1));
        assert!(entry.on_layer(2));

        assert!(entry.layers_overlap(0b001));
        assert!(!entry.layers_overlap(0b010));
        assert!(entry.layers_overlap(0b111));
    }

    #[test]
    fn test_clear() {
        let mut index = SpatialIndex::new();
        index.rebuild(vec![make_entry(0, (0.0, 0.0), (10.0, 10.0), 1)]);
        assert!(!index.is_empty());

        index.clear();
        assert!(index.is_empty());
    }

    #[test]
    fn test_iter() {
        let mut index = SpatialIndex::new();
        index.rebuild(vec![
            make_entry(0, (0.0, 0.0), (10.0, 10.0), 1),
            make_entry(1, (20.0, 20.0), (30.0, 30.0), 1),
        ]);

        let entries: Vec<_> = index.iter().collect();
        assert_eq!(entries.len(), 2);
    }
}

//! CodeYourPCB World
//!
//! ECS-based board model using bevy_ecs.
//! Provides the runtime representation of PCB designs.
//!
//! # Architecture
//!
//! This crate uses an Entity Component System (ECS) architecture from bevy_ecs.
//! PCB elements are represented as entities composed of small, focused components.
//!
//! ## Why ECS?
//!
//! - **Composition over inheritance**: Combine components flexibly
//! - **Cache-friendly**: Contiguous memory layout for fast iteration
//! - **Parallel queries**: bevy_ecs supports parallel iteration
//! - **Decoupled systems**: Components and systems are independent
//!
//! # Components
//!
//! Components are organized into categories:
//!
//! - **Position**: [`Position`], [`Rotation`] - spatial placement
//! - **Electrical**: [`NetId`], [`RefDes`], [`Value`], [`NetConnections`] - electrical properties
//! - **Physical**: [`Layer`], [`FootprintRef`], [`Pad`], [`PadShape`] - physical properties
//! - **Board**: [`Board`], [`BoardSize`], [`LayerStack`] - board-level properties
//! - **Metadata**: [`SourceSpan`], [`ComponentKind`] - source tracking
//!
//! # Entity Examples
//!
//! A resistor entity might have:
//! ```text
//! Entity: R1
//!   - RefDes("R1")
//!   - Value("10k")
//!   - Position at (10mm, 20mm)
//!   - Rotation at 90 degrees
//!   - FootprintRef("0402")
//!   - NetConnections { "1" -> VCC, "2" -> GND }
//!   - SourceSpan pointing to source file
//! ```
//!
//! A board entity might have:
//! ```text
//! Entity: Board
//!   - Board (marker)
//!   - BoardSize(100mm x 80mm)
//!   - LayerStack(4 layers)
//! ```
//!
//! # Example Usage
//!
//! ```
//! use bevy_ecs::prelude::*;
//! use cypcb_world::*;
//! use cypcb_core::Point;
//!
//! // Create a world
//! let mut world = World::new();
//!
//! // Spawn a board entity
//! world.spawn((
//!     Board,
//!     BoardSize::from_mm(100.0, 80.0),
//!     LayerStack::new(2),
//! ));
//!
//! // Spawn a resistor entity
//! let vcc = NetId::new(0);
//! let gnd = NetId::new(1);
//!
//! let mut nets = NetConnections::new();
//! nets.add(PinConnection::new("1", vcc));
//! nets.add(PinConnection::new("2", gnd));
//!
//! world.spawn((
//!     RefDes::new("R1"),
//!     Value::new("10k"),
//!     Position::from_mm(10.0, 20.0),
//!     Rotation::from_degrees(90.0),
//!     FootprintRef::new("0402"),
//!     nets,
//! ));
//!
//! // Query all components with position
//! let mut query = world.query::<(&RefDes, &Position)>();
//! for (refdes, pos) in query.iter(&world) {
//!     println!("{} at {}", refdes, pos);
//! }
//! ```

pub mod components;
pub mod footprint;
pub mod registry;
pub mod spatial;
#[cfg(feature = "sync")]
pub mod sync;
pub mod world;

// Re-export all component types at crate root for convenience
pub use components::{
    // Board components
    Board,
    BoardSize,
    LayerStack,
    // Electrical components
    NetConnections,
    NetId,
    PinConnection,
    RefDes,
    Value,
    // Metadata components
    ComponentKind,
    SourceSpan,
    // Physical components
    FootprintRef,
    Layer,
    Pad,
    PadShape,
    // Position components
    Position,
    Rotation,
    // Trace components
    trace::{Trace, TraceSegment, TraceSource, Via},
};

