        assert!(Layer::TopCopper.is_top());
        assert!(Layer::TopSilk.is_top());
        assert!(!Layer::TopCopper.is_bottom());

        assert!(Layer::BottomCopper.is_bottom());
        assert!(Layer::BottomMask.is_bottom());
        assert!(!Layer::BottomCopper.is_top());
    }

    #[test]
